#!/usr/bin/perl
use strict;
use warnings;
use CGI;
use GD;

my $query = new CGI;
my $lookfor = $query->param('id') || "";

# 1. Load Data (Fix: Split on any whitespace \s+ to handle spaces/tabs)
my %HB;
while (<DATA>) {
    chomp;
    if ($_ =~ /^(\d+)\s+(.*)$/) {
        $HB{$1} = $2;
    }
}

# 2. Initialize Image
my $im = new GD::Image(400, 25);

# First color allocated is the background
my $white = $im->colorAllocate(255, 255, 255);
my $black = $im->colorAllocate(0, 0, 0);
my $blue  = $im->colorAllocate(0, 0, 255);

# 3. Allocate Density Colors
my @bloom_colors_rgb = ("255,255,255", "248,236,224", "246,227,206", "245,208,169", "247,190,129", "250,172,88", "254,154,46", "255,128,0", "223,116,1", "180,95,4", "97,57,8");
my @bloom_density;
for my $color_str (@bloom_colors_rgb) {
    my @rgb = split(',', $color_str);
    push @bloom_density, $im->colorAllocate(@rgb);
}

$im->transparent($white);
$im->interlaced('true');

# 4. Process FT params
my %FT;
if ($query->param('FT')) {
    foreach my $i (split(/,/, $query->param('FT'))) {
        $FT{$i}++;
    }
}

# 5. Drawing Logic
if ($lookfor && exists $HB{$lookfor}) {
    my @counts = split(/\s+/, $HB{$lookfor});
    
    # Total is the last element (e.g., index 12)
    my $total_str = $counts[12] // "(1)";
    $total_str =~ s/[()]*//g;
    my $total = $total_str || 1;

    $im->string(gdSmallFont, 358, 10, "n=$total", $black);

    for (my $i = 0; $i < 12; $i++) {
        my $val = $counts[$i] || 0;
        
        # Calculate percentage (0 to 100)
        my $percent = ($total > 0) ? int(100 * $val / $total) : 0;

        # Map percentage to index 0-10
        # 0% = 0, 1-10% = 1, 11-20% = 2 ... 91-100% = 10
        my $idx = 0;
        if ($percent > 0) {
            $idx = int(($percent - 1) / 10) + 1;
        }
        $idx = 10 if $idx > 10;

        my $left = 60 + ($i * 24);
        my $right = $left + 24;

        # Draw the colored box
        $im->filledRectangle($left, 0, $right, 24, $bloom_density[$idx]);

        # Draw blue footer if FT match
        if ($FT{$i}) {
            $im->filledRectangle($left, 22, $right, 24, $blue);
        }

        # Draw the count text
        $im->string(gdSmallFont, $left + 5, 10, "$val", $black);
    }
}

# 6. Draw Frames and Labels
$im->rectangle(0, 0, 399, 24, $black);
my $l = 60;
my @months = ("Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec");
foreach my $m (@months) {
    $im->string(gdTinyFont, $l + 4, 1, $m, $black);
    $im->rectangle($l, 0, $l + 24, 24, $black);
    $l += 24;
}

# 7. Output
binmode STDOUT;
print $query->header(-type => 'image/gif', -expires => '-1d');
print $im->gif;

__END__
